:root{
--bg:oklch(98.2% .004 255);--panel:oklch(99.7% .0015 255);--sunk:oklch(97.1% .005 255);--hover:oklch(96.2% .007 255);
--line:oklch(91.6% .007 255);--line2:oklch(94.6% .005 255);
--ink:oklch(22% .012 255);--ink2:oklch(36% .012 255);--mut:oklch(50% .013 255);--faint:oklch(68% .01 255);
--acc:oklch(55% .19 256);--acc-bg:oklch(95.6% .026 256);
--vio:oklch(52% .2 295);--vio-bg:oklch(95.8% .03 295);
--ok:oklch(52% .14 150);--ok-bg:oklch(96.4% .032 150);
--bad:oklch(53% .19 27);--bad-bg:oklch(96.6% .02 27);
--warn:oklch(52% .12 66);--warn-bg:oklch(96.2% .045 85);
--sh:0 1px 2px oklch(30% .02 255/.06);--sh2:0 1px 3px oklch(30% .02 255/.08),0 16px 40px -12px oklch(30% .04 255/.26);
--ease:cubic-bezier(.22,1,.36,1);--mono:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
*{box-sizing:border-box;margin:0}
html{background:var(--bg);color:var(--ink);font-family:Geist,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%}
body{line-height:1.45;font-size:15px;-webkit-font-smoothing:antialiased;background:var(--bg);min-height:100vh}
a{color:var(--acc);text-underline-offset:3px}
button{font:inherit;color:inherit}
code,.mono{font-family:var(--mono)}
:focus-visible{outline:3px solid var(--acc);outline-offset:2px;border-radius:8px}
[hidden]{display:none!important}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
svg.i{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}
main{max-width:1240px;margin:0 auto;padding:24px 20px 72px}
h1{font-size:34px;line-height:1.1;letter-spacing:-.035em;font-weight:700}
h2{font-size:19px;letter-spacing:-.02em;font-weight:650}
.lede{font-size:16px;color:var(--mut);margin-top:6px;max-width:58ch}
.sec{margin-top:36px}
.sec-h{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:12px;flex-wrap:wrap}
.sec-h p{color:var(--mut);font-size:13.5px}
.btn{display:inline-flex;align-items:center;gap:7px;height:36px;padding:0 14px;border-radius:10px;border:1px solid var(--line);background:var(--panel);color:var(--ink);font-weight:600;font-size:13.5px;text-decoration:none;cursor:pointer;white-space:nowrap;box-shadow:var(--sh)}
.btn:hover{background:var(--hover)}
.btn.pri{background:var(--vio);border-color:transparent;color:oklch(99% .005 295)}
.btn.pri:hover{background:oklch(47% .2 295)}
.tile{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:8px;flex:none;color:oklch(99% .005 255)}
.tile svg.i{width:16px;height:16px}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;box-shadow:var(--sh)}
.back{display:inline-flex;align-items:center;gap:6px;font-size:13.5px;color:var(--mut);text-decoration:none}
.back:hover{color:var(--ink)}
.av{width:40px;height:40px;border-radius:10px;background:var(--sunk);border:1px solid var(--line);flex:none;object-fit:cover}
/* start view */
.lh-top{display:flex;gap:16px;align-items:flex-start}
