.ask{display:flex;gap:8px;align-items:center;margin-top:22px;max-width:640px;padding:6px 6px 6px 16px}
.ask svg.i{color:var(--mut)}
.ask input{flex:1;min-width:0;font:inherit;font-size:15.5px;border:0;background:none;color:var(--ink);padding:8px 0;outline:0}
.mode{display:inline-flex;gap:4px;margin-top:22px;padding:4px;border-radius:12px;background:var(--sunk);border:1px solid var(--line)}
.mode button{display:inline-flex;align-items:center;gap:7px;height:34px;padding:0 14px;border:0;border-radius:9px;background:none;font-weight:600;font-size:13.5px;color:var(--mut);cursor:pointer}
.mode button svg.i{width:15px;height:15px}
.mode button[aria-pressed=true]{background:var(--panel);color:var(--ink);box-shadow:var(--sh)}
.ask.top{margin-top:10px}
.hint{font-size:13px;color:var(--mut);margin-top:8px;max-width:640px}
.steps{list-style:none;padding:0;margin-top:12px;max-width:760px;display:grid;gap:8px}
.steps li{display:grid;grid-template-columns:28px minmax(0,1fr);gap:4px 12px;padding:12px 14px}
.steps .n{grid-row:1/span 3;width:26px;height:26px;border-radius:99px;display:grid;place-items:center;font-size:13px;font-weight:700;background:var(--vio-bg);color:var(--vio)}
.steps b{font-size:14.5px}
.steps span{font-size:13px;color:var(--mut)}
.steps .opt{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--vio);margin-left:8px}
.steps .dw-acts{margin-top:6px}
.code{display:flex;align-items:center;gap:8px;margin-top:4px;background:var(--sunk);border:1px solid var(--line);border-radius:9px;padding:6px 6px 6px 12px;font:12.5px var(--mono);overflow-x:auto}
.code code{flex:1;white-space:pre}
.code .btn{height:30px;padding:0 10px;flex:none}
.cmd{display:flex;gap:10px;align-items:flex-start;justify-content:space-between;margin-top:10px;max-width:640px;padding:12px 12px 12px 16px;font-size:13px}
.cmd code{white-space:pre;overflow-x:auto}
.flow{padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin-top:14px;overflow:hidden}
.flow li{list-style:none;display:flex;gap:12px;align-items:flex-start;padding:16px 18px;position:relative}
.flow li+li{border-left:1px solid var(--line2)}
.flow b{display:block;font-size:14.5px}
.flow span{font-size:13px;color:var(--mut)}
.flow .tile{background:var(--vio-bg);color:var(--vio)}
.alist{list-style:none;padding:0;overflow:hidden}
.alist li+li{border-top:1px solid var(--line2)}
.alist a{display:grid;grid-template-columns:40px minmax(0,1fr) 220px auto;gap:4px 16px;align-items:center;padding:14px 18px;color:inherit;text-decoration:none}
.alist a:hover{background:var(--hover)}
.alist .nm{font-weight:650;font-size:15.5px;letter-spacing:-.01em}
.alist .nm small{display:block;font-weight:400;font-size:12.5px;color:var(--mut)}
.alist .go{color:var(--vio);font-weight:600;font-size:13.5px;display:inline-flex;gap:4px;align-items:center}
.minis{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
/* chips */
.chip{display:inline-flex;align-items:center;gap:5px;height:24px;padding:0 9px;border-radius:99px;font-size:12.5px;font-weight:600;background:var(--sunk);color:var(--ink2);border:1px solid transparent;white-space:nowrap}
.chip svg.i{width:13px;height:13px}
.c-stale{background:var(--bad-bg);color:var(--bad)}.c-unchecked{background:var(--warn-bg);color:var(--warn)}
.c-quiet{background:var(--sunk);color:var(--mut)}.c-aging{background:var(--warn-bg);color:var(--warn)}.c-fresh{background:var(--ok-bg);color:var(--ok)}
.c-gap{background:var(--vio-bg);color:var(--vio)}
button.chip{cursor:pointer}
button.chip[aria-pressed=true]{border-color:currentColor}
/* report: head and health */
.rh{display:flex;gap:14px;align-items:center;margin-top:10px;flex-wrap:wrap}
.rh h1{font-size:28px}
.rh .meta{color:var(--mut);font-size:13.5px;margin-top:2px}
.rh .acts{margin-left:auto;display:flex;gap:8px}
.health{margin-top:18px;padding:14px 16px;display:grid;gap:10px}
.bar{display:flex;height:10px;border-radius:99px;overflow:hidden;background:var(--line2);gap:2px}
.bar i{display:block;height:100%}
.b-stale{background:var(--bad)}.b-unchecked{background:oklch(72% .15 75)}.b-quiet{background:var(--faint)}.b-aging{background:oklch(82% .12 85)}.b-fresh{background:var(--ok)}
.hrow{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.hrow .lbl{font-size:13px;color:var(--mut);margin-right:4px}
.hrow .sp{flex:1}
/* kanban */
.board{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;align-items:start}
.col{background:var(--sunk);border:1px solid var(--line);border-radius:14px;display:flex;flex-direction:column;min-width:0;max-height:640px}
.col-h{display:flex;align-items:center;gap:10px;padding:12px 12px 10px}
.col-h b{font-size:14.5px;letter-spacing:-.01em}
.col-h .n{margin-left:auto;font-size:12.5px;font-weight:600;color:var(--mut);background:var(--panel);border:1px solid var(--line);border-radius:99px;padding:1px 8px}
.col-s{font-size:12.5px;color:var(--mut);padding:0 12px 10px;line-height:1.4}
.col-b{display:flex;flex-direction:column;gap:8px;padding:0 8px 8px;overflow-y:auto}
.k-document .tile{background:var(--bad)}.k-refresh .tile{background:oklch(64% .14 70)}.k-feature .tile{background:var(--acc)}.k-content .tile{background:var(--vio)}
.k-automate .tile{background:var(--ok)}.k-quickstart .tile{background:var(--ink)}
.kc{display:flex;flex-direction:column;gap:6px;text-align:left;width:100%;background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:11px 12px;cursor:pointer;box-shadow:var(--sh);transition:border-color .15s,transform .2s var(--ease)}
